\@ifnextchar[{\@xfootnote}{\refstepcounter
   {mpfootnote}\protected@xdef\relax{\alph{mpfootnote}}\@footnotemark\@mpfootnotetext}{Problem~\ref{prob:two-stage} is a two-stage problem, a special form of a bilevel problem; the outer optimization contains the value of the lower-level problem, not its argmin. Solving a bilevel problem directly is hard since it requires implicitly differentiating the inner optimality conditions. Instead, in the two-stage case, the envelope theorem supplies the gradient
directly from the duals the inner solver already returns.}\label{prob:two-stage}
\begin{align*}
&\text{Design (first stage):}\quad \min_{\theta \in \Theta}\
J(\theta) = J_{\mathrm{des}}(\theta) + J_{\mathrm{sc}}^\star(\mathcal Z_0;\theta),\\
&\text{Control (second stage):}\quad J_{\mathrm{sc}}^\star(\mathcal Z_0;\theta)\ \text{as in
\eqref{eq:Jstoch_N} or \eqref{eq:Jstoch_infty}}.
\end{align*}

\label{as:env}
On a neighborhood $\Theta_0$ of the design point $\theta$:
\emph{(A.I)}~for each $\theta\in\Theta_0$, \eqref{eq:generic} is convex in $z$,
its data $(\phi,g,G)$ are jointly $C^1$ in $(z,\theta)$, and Slater's condition
holds, so strong duality holds with an attained primal-dual solution;
\emph{(A.II)}~the primal minimizer $z^\star(\theta)$ is unique;
\emph{(A.III)}~the primal--dual solution is \emph{nondegenerate} and strictly
complementary, so the dual $(\mu^\star,S^\star)$ is unique
\cite{alizadeh1997complementarity,shapiro1997differentiability};
\emph{(A.IV)}~$\theta$ enters \eqref{eq:generic} only through finitely many data
objects $D(\theta)$ (e.g.\ $A_\theta,B_\theta,C_\theta$) that are $C^1$
in $\theta$.

\label{prop:envelope}
Under Assumption~\ref{as:env}, $J^\star$ is differentiable at $\theta$ and
\begin{equation}\label{eq:envelope}
\nabla_\theta J^\star(\theta) = \nabla_\theta \mathfrak L(z^\star,\mu^\star,S^\star,\theta)
= \partial_\theta J + \langle \mu^\star, \partial_\theta g\rangle
- \langle S^\star, \partial_\theta G\rangle,
\end{equation}
all partials evaluated at $(z^\star,\theta)$ with $z^\star,\mu^\star,S^\star$
held fixed.

\label{lem:stagecost}
For a causal law $u_k = u_k(\mathcal{Z}_k, p_0)$,
\begin{equation*}
\mathbb{E}\,\ell(x_k,u_k) = \!\iint \ell(x_k,u_k)\,
p(x_k \mid \mathcal{Z}_k;\theta)\, p(\mathcal{Z}_k;\theta)\, dx_k\, d\mathcal{Z}_k.
\end{equation*}
